    def is_valid_star(x, y, s):
        # Check if the star centered at (x, y) with size s is within bounds
        return 0 <= x - s < n and 0 <= x + s < n and 0 <= y - s < m and 0 <= y + s < m

    stars = []
    visited = set()

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and (i, j) not in visited:
