    return True

def find_stars(n, m, grid):
    stars = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not visited[i][j]:
                s = 1
                while is_valid_star(i, j, s, n, m, grid):
