def draw_stars(n, m, grid):
    def is_valid(x, y):
        return 1 <= x <= n and 1 <= y <= m

    def get_cluster(x, y):
        stack = [(x, y)]
        cluster = set()
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in cluster:
                continue
            cluster.add((cx, cy))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny) and grid[nx-1][ny-1] == '*':
                    stack.append((nx, ny))
        return cluster

    stars = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not visited[i][j]:
                cluster = get_cluster(i+1, j+1)
                min_size = float('inf')
                for cx, cy in cluster:
                    visited[cx-1][cy-1] = True
                    size = max(abs(cx-i-1), abs(cy-j-1))
                    min_size = min(min_size, size)
                stars.append((i+1, j+1, min_size))

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not any(abs(i+1-sx) <= sz and abs(j+1-sy) <= sz for sx, sy, sz in stars):
                return "-1"

    return len(stars), stars

